#!/usr/bin/env python3
"""Probe which PDF-related libraries are importable in this environment."""
import importlib

mods = [
    "pypdf", "PyPDF2", "reportlab", "fpdf", "fitz", "pdfplumber",
    "pdfminer", "PIL", "pikepdf", "weasyprint",
]
for m in mods:
    try:
        importlib.import_module(m)
        print(f"OK   {m}")
    except Exception as e:
        print(f"MISS {m} ({type(e).__name__})")

